  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://interfast-backend-95ww.onrender.com/api/bot/buscar-cliente?query=${encodeURIComponent(query)}`,
    headers: {
      'x-api-key': 'InterfastN8NBot2026!'
    }
  });

  if (typeof response === 'string') return response;
  return response.formatted_message || JSON.stringify(response);
} catch(e) {
