let body;
try {
  body = typeof query === 'string' ? JSON.parse(query) : query;
} catch(e) {
  return 'Error: El input debe ser un JSON válido. ' + e.message;
}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://interfast-backend-95ww.onrender.com/api/bot/crear-ticket',
    headers: {
      'x-api-key': 'InterfastN8NBot2026!',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  });

  if (response && response.duplicate_prevented) {
    return `¡ATENCIÓN! ${response.message}`;
  }

  return JSON.stringify(response);
} catch(e) {
  return 'Error al crear ticket en el CRM: ' + e.message;
}

for (const item of $input.all()) {
  const body = item.json.body || {};
  const payload = body.payload || {};

  // 1. Solo eventos de mensaje e ignorar propios/estados
  if (body.event !== "message" || payload.fromMe === true || payload.from === "status@broadcast") {
    item.json.numero_limpio = "error_extraccion";
    continue;
  }

  // 2. Extraer el número de teléfono limpio
  let rawNumber = payload._data?.key?.remoteJidAlt || payload.from || "error_no_number";
  item.json.numero_limpio = rawNumber.split('@')[0];

  // 3. Detectar Tipo de Mensaje Real de WAHA (chat, ptt, image, audio)
  item.json.tipo_mensaje = payload.type || "chat"; 

  // 4. Extractor de URL Inteligente (Busca en todas las capas de WAHA)
  let rawUrl = payload.url || payload.media?.url || payload.message?.imageMessage?.url || payload.message?.audioMessage?.url || null;

  // Guardamos la URL unificada en una sola variable limpia para n8n
  item.json.url_archivo = rawUrl;
}

return $input.all();

let inputData = $input.all();
let invoiceIds = [];

if (inputData[0] && Array.isArray(inputData[0].json)) {
    invoiceIds = inputData[0].json.map(item => item.id || item.invoiceId);
} else if (inputData[0] && inputData[0].json && Array.isArray(inputData[0].json.invoices)) {
    invoiceIds = inputData[0].json.invoices.map(item => item.id || item.invoiceId);
} else {
    invoiceIds = inputData.map(item => item.json.id || item.json.invoiceId).filter(id => id !== undefined);
}

return [{ json: { invoiceIds: invoiceIds } }];

