      'x-api-key': 'InterfastN8NBot2026!' // Lo dejo por consistencia con tus otros endpoints blindados
    }
  });
  return JSON.stringify(response);
} catch(e) {
  return 'Error al hacer ping a la antena en el backend: ' + e.message;
}

let body = typeof query === 'string' ? JSON.parse(query) : query;
try {
  // Aseguramos que la dirección se incluya en las notas si el endpoint no tiene un campo 'address' específico
  const direccion = body.address ? " Dirección: " + body.address : " Dirección: No proporcionada";

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://interfast-backend-95ww.onrender.com/api/leads',
    headers: {
      'x-api-key': 'InterfastN8NBot2026!',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      name: body.name,
      phone: body.phone,
      notes: "[AGENTE N8N] " + body.notes + direccion,
      status: "NUEVO"
    })
  });
  return "Alta registrada exitosamente con dirección en el CRM.";
} catch(e) {
  return 'Error al registrar el alta: ' + e.message;
}

